do $migration$
declare
  catalog jsonb := $catalog$[{"id":"renuvia","slug":"renuvia","legacySlugs":["expirely"],"name":"Renuvia","tagline":"Convierte cada renovación en un expediente listo para actuar.","tagline_en":"Turn every renewal into a dossier ready for action.","shortDescription":"Un radar privado que convierte fechas de renovación en expedientes con preparación, requisitos e historial.","shortDescription_en":"A private radar that turns renewal dates into dossiers with readiness, requirements, and history.","longDescription":"Renuvia reúne tus fechas de renovación en un Radar vivo y convierte cada plazo en un expediente: emisor, referencia, checklist, documentos necesarios, siguiente acción e historial.","longDescription_en":"Renuvia brings renewal dates into a live Radar and turns each deadline into a dossier: issuer, reference, checklist, required documents, next action, and history.","problem":"Renovar no consiste solo en recordar una fecha: hay requisitos, documentos, responsables y decisiones previas que preparar. La información suele quedar repartida y la urgencia aparece demasiado tarde.","problem_en":"Renewing is not just remembering a date: there are requirements, documents, owners, and decisions to prepare. The information is scattered and urgency arrives too late.","benefits":["Radar de preparación: Ve qué expediente necesita una decisión, un documento o contacto hoy.","Playbooks de renovación: Adapta el checklist a pasaportes, inspecciones, seguros, contratos, garantías y permisos.","Evidencia organizada: Conserva emisor, referencia, documentos requeridos, fechas y trazabilidad de cada renovación.","Privacidad local: Añade manualmente sin conexión o captura con OCR en el dispositivo; todo queda revisable antes de guardar."],"benefits_en":["Readiness Radar: See which dossier needs a decision, document, or contact today.","Renewal playbooks: Adapt the checklist to passports, inspections, insurance, contracts, warranties, and permits.","Organized evidence: Keep issuer, reference, required documents, dates, and renewal history together.","Local privacy: Add entries offline or capture with on-device OCR; review everything before saving."],"features":["Radar de preparación: Ordena expedientes por urgencia, preparación y siguiente acción.","Playbooks: Inicia checklists específicos para identidad, vehículo, seguro, contrato, garantía, suscripción o permiso.","Requisitos: Marca documentos reunidos y pendientes dentro del expediente.","Historial de renovación: Conserva la fecha anterior, la nueva y cuándo registraste el cambio.","Captura revisable: Usa cámara, Fotos, PDF o código de barras con OCR local y confirma cada campo.","Privacidad y control: Sin cuenta, entrada manual offline, exportación CSV/JSON e iCloud opcional."],"features_en":["Readiness Radar: Sort dossiers by urgency, readiness, and next action.","Playbooks: Start focused checklists for identity, vehicle, insurance, contracts, warranties, subscriptions, or permits.","Requirements: Mark gathered and missing documents inside each dossier.","Renewal history: Preserve the previous date, the new date, and when the change was recorded.","Reviewable capture: Use camera, Photos, PDF, or barcode with on-device OCR and confirm every field.","Privacy and control: No account, offline manual entry, CSV/JSON export, and optional iCloud."],"audience":"Personas y hogares que necesitan preparar renovaciones reales —identidad, vehículo, seguros, contratos, garantías, suscripciones y permisos— sin depender de hojas de cálculo.","audience_en":"People and households who need to prepare real renewals—identity, vehicles, insurance, contracts, warranties, subscriptions, and permits—without spreadsheets.","status":"development","featured":true,"category":"Productividad","category_en":"Productivity","platform":["iOS","iPadOS"],"supportEmail":"romerodev.app+renuvia@gmail.com","iconUrl":"assets/images/renuvia/renuvia-icon.png","coverImageUrl":"assets/images/renuvia/screens/01_radar_es.png","screenshots":["01_radar","02_scanner","03_review","04_vault","05_renewals","06_analytics","07_calendar","08_alerts","09_categories","10_privacy"],"primaryCtaLabel":"Conocer el lanzamiento","primaryCtaLabel_en":"Follow the launch","primaryCtaUrl":"/es/casos/renuvia/soporte/","secondaryCtaLabel":"Soporte de la app","secondaryCtaLabel_en":"App support","secondaryCtaUrl":"/es/casos/renuvia/soporte/","colorPrimary":"#4f46e5","colorSecondary":"#22d3ee","updatedAt":"2026-08-28","promotionalText":"No solo recuerdes la fecha: prepara el expediente, completa requisitos y conserva la historia de cada renovación.","promotionalText_en":"Do more than remember the date: prepare the dossier, complete requirements, and keep every renewal history.","seo":{"title":"Renuvia: expedientes privados de renovación con Radar | RomeroDev","description":"Prepara renovaciones de identidad, vehículos, seguros, contratos, garantías y permisos con expedientes, checklist, documentos y Radar local.","keywords":"renovación,expediente,radar,checklist,documentos,seguro,contrato,garantía,permiso,OCR","keywords_en":"renewal,dossier,radar,checklist,documents,insurance,contract,warranty,permit,OCR"},"faq":[{"question":"¿Renuvia sube mis documentos a un servidor?","question_en":"Does Renuvia upload my documents to a server?","answer":"No en el flujo local: la entrada manual, el OCR, las imágenes, los PDF y la revisión se procesan en el dispositivo. Si activas iCloud o analíticas opcionales, se aplican sus condiciones y la información descrita en la Política de privacidad.","answer_en":"Not in the local flow: manual entry, OCR, images, PDFs, and review are processed on device. If you enable iCloud or optional analytics, their terms and the Privacy Policy apply."},{"question":"¿Puedo usarlo sin cámara ni cuenta?","question_en":"Can I use it without a camera or account?","answer":"Sí. Renuvia funciona sin cuenta y la entrada manual nunca depende de la cámara, OCR, IA, red o permisos.","answer_en":"Yes. Renuvia works without an account, and manual entry never depends on the camera, OCR, AI, network, or permissions."},{"question":"¿Qué ocurre con una fecha detectada por OCR?","question_en":"What happens to a date detected by OCR?","answer":"Renuvia propone un título y una fecha junto con la evidencia disponible. Debes revisar y confirmar los campos antes de crear un vencimiento o una acción.","answer_en":"Renuvia proposes a title and date with the available evidence. You must review and confirm fields before creating an expiration or action."},{"question":"¿Cómo cancelo o restauro Renuvia Pro?","question_en":"How do I cancel or restore Renuvia Pro?","answer":"Gestiona o cancela desde Ajustes > tu nombre > Suscripciones. Para recuperar una compra, abre Renuvia Pro y pulsa Restaurar compras con el mismo Apple Account.","answer_en":"Manage or cancel in Settings > your name > Subscriptions. To recover a purchase, open Renuvia Pro and tap Restore Purchases with the same Apple Account."},{"question":"¿Renuvia ofrece asesoramiento sobre fechas legales o médicas?","question_en":"Does Renuvia provide legal or medical deadline advice?","answer":"No. Es una herramienta de organización y recordatorio. Verifica siempre las condiciones con el documento original o con un profesional cualificado.","answer_en":"No. It is an organization and reminder tool. Always verify conditions against the original document or with a qualified professional."}],"legal":{"privacy":{"title":"Política de privacidad de Renuvia","title_en":"Renuvia Privacy Policy","updatedAt":"2026-08-28","body":["Esta política se aplica internacionalmente a Renuvia y explica qué información puede tratar la aplicación, para qué se utiliza y qué opciones tienes. Los derechos imperativos de tu país de residencia prevalecen cuando sean más favorables.","## 1. Responsable y contacto","El responsable es Lester Romero Bernardo (RomeroDev), con domicilio en Valencia, España. Contacto de privacidad y soporte: romerodev.app+renuvia@gmail.com.","## 2. Datos que puede tratar Renuvia","Renuvia trata los datos que introduces o confirmas, como títulos, fechas de vencimiento, categorías, notas, costes, condiciones y el historial de renovaciones. Si importas una imagen o un PDF, puede crear una copia temporal para el análisis local. La app no necesita una cuenta, nombre, teléfono ni correo para funcionar.","## 3. Procesamiento local y permisos","La entrada manual, la extracción de texto, el OCR, la revisión, la base de datos local, los recordatorios y las exportaciones se procesan en tu dispositivo. La cámara, Fotos, Archivos, Calendario, Recordatorios y Notificaciones solo se solicitan cuando activas la función correspondiente. Puedes seguir utilizando la entrada manual sin conceder permisos de captura.","## 4. iCloud y servicios de Apple","Si activas la sincronización, Renuvia utiliza el contenedor privado de iCloud asociado a tu Apple ID para sincronizar los datos que la función necesita. Apple trata esos datos conforme a sus políticas y controles. StoreKit procesa las compras y suscripciones; Renuvia recibe el estado técnico de la transacción, no los datos completos de tu tarjeta.","## 5. Diagnósticos opcionales","Si activas Analíticas de producto, los servicios configurados pueden recibir eventos técnicos y agregados sobre el uso de funciones, rendimiento y fallos. No se envían títulos, texto OCR, imágenes, PDF, fechas, costes, notas, identificadores documentales ni el contenido de tus renovaciones. Esta opción está desactivada por defecto y puede revocarse en Ajustes.","## 6. Conservación, eliminación y exportación","Los registros permanecen en tu dispositivo o en tu contenedor privado de iCloud mientras los mantengas. Puedes eliminar elementos, borrar todos los datos y exportar CSV/JSON desde la aplicación. Las copias temporales controladas por Renuvia se eliminan conforme al flujo de captura; la app nunca borra tus originales de Fotos o Archivos.","## 7. Compartición y transferencias internacionales","No vendemos tus datos, no creamos perfiles publicitarios y no rastreamos tu actividad entre aplicaciones o sitios web. Solo se comparte información con Apple o proveedores técnicos cuando activas la función que los necesita, cuando es necesario para prestar el servicio o cuando la ley lo exige. Cualquier transferencia internacional se realizará con las garantías exigidas por la normativa aplicable.","## 8. Derechos y menores","Según tu lugar de residencia, puedes solicitar acceso, rectificación, supresión, limitación, oposición, portabilidad o retirada del consentimiento escribiendo al contacto anterior. También puedes reclamar ante la autoridad de protección de datos competente. Renuvia es una herramienta general y no está dirigida a menores; no introduzcas datos de menores sin la autoridad y salvaguardas necesarias.","## 9. Cambios","Publicaremos aquí los cambios materiales con una nueva fecha de actualización y, cuando proceda, un aviso dentro de la aplicación."],"body_en":["This policy applies internationally to Renuvia and explains what information the app may process, why it is used, and what choices you have. Mandatory rights in your country of residence prevail where they provide stronger protection.","## 1. Controller and contact","The controller is Lester Romero Bernardo (RomeroDev), based in Valencia, Spain. Privacy and support contact: romerodev.app+renuvia@gmail.com.","## 2. Data Renuvia may process","Renuvia processes information you enter or confirm, such as titles, expiration dates, categories, notes, costs, conditions, and renewal history. If you import an image or PDF, it may create a temporary copy for local analysis. The app does not require an account, name, phone number, or email to work.","## 3. On-device processing and permissions","Manual entry, text extraction, OCR, review, the local database, reminders, and exports are processed on your device. Camera, Photos, Files, Calendar, Reminders, and Notifications are requested only when you activate the related feature. You can keep using manual entry without granting capture permissions.","## 4. iCloud and Apple services","If you enable sync, Renuvia uses the private iCloud container associated with your Apple Account to sync the data required by that feature. Apple handles that data under its own policies and controls. StoreKit processes purchases and subscriptions; Renuvia receives technical transaction entitlement state, not your complete card details.","## 5. Optional diagnostics","If you enable Product Analytics, configured services may receive technical and aggregated events about feature use, performance, and crashes. Titles, OCR text, images, PDFs, dates, costs, notes, document identifiers, and renewal content are not sent. This option is off by default and can be revoked in Settings.","## 6. Retention, deletion, and export","Records remain on your device or in your private iCloud container while you keep them. You can delete items, erase all data, and export CSV/JSON from the app. Renuvia-controlled temporary copies are removed according to the capture flow; the app never deletes your originals in Photos or Files.","## 7. Sharing and international transfers","We do not sell your data, create advertising profiles, or track you across apps or websites. Information is shared with Apple or technical providers only when you enable a feature that needs them, when required to provide the service, or when the law requires it. International transfers will use the safeguards required by applicable law.","## 8. Rights and children","Depending on where you live, you may request access, rectification, deletion, restriction, objection, portability, or withdrawal of consent by contacting us above. You may also complain to your competent data protection authority. Renuvia is a general-purpose tool and is not directed to children; do not enter a child's data without the required authority and safeguards.","## 9. Changes","Material changes will be published here with a new update date and, where appropriate, an in-app notice."]},"terms":{"title":"Términos de uso de Renuvia","title_en":"Renuvia Terms of Use","updatedAt":"2026-08-28","body":["Estos términos regulan el uso internacional de Renuvia. Al descargar o utilizar la aplicación aceptas estos términos, la Política de privacidad y las reglas aplicables del App Store. Los derechos irrenunciables de consumidores y usuarios no quedan limitados.","## 1. Servicio","Renuvia es una herramienta de organización de fechas, documentos y renovaciones. No presta asesoramiento legal, financiero, médico, fiscal o contractual, no garantiza que una fecha sea correcta y no sustituye la revisión de documentos ni la consulta con un profesional.","## 2. Tus datos y responsabilidad","Conservas los derechos sobre el contenido que introduces o importas y confirmas que puedes utilizarlo. Eres responsable de revisar toda fecha, título, coste, recordatorio, exportación y acción de calendario antes de confiar en ella, así como de proteger tu dispositivo, Apple ID y copias exportadas.","## 3. Uso aceptable","No utilices Renuvia para fines ilícitos, fraude, suplantación, acceso no autorizado, malware, vigilancia indebida, infracción de derechos o para introducir datos de terceros sin autorización. No intentes interferir con la aplicación ni eludir sus controles, salvo cuando la ley aplicable lo permita expresamente.","## 4. OCR y automatización","El OCR, la detección de códigos de barras y las sugerencias automáticas pueden omitir datos, equivocarse o interpretar de forma incompleta una fuente. La revisión de la persona usuaria es obligatoria antes de guardar un resultado o crear recordatorios, eventos, acciones o renovaciones.","## 5. Compras y servicios de Apple","Las funciones Pro se ofrecen mediante Apple In-App Purchase y están sujetas a las condiciones de suscripción publicadas para Renuvia y a la información que Apple muestra antes de comprar. Apple proporciona el App Store, pagos, iCloud y otras plataformas de terceros de forma independiente.","## 6. Propiedad intelectual","Renuvia, su código, marca, diseño, textos y materiales propios pertenecen a Lester Romero Bernardo (RomeroDev) o a sus licenciantes. Se concede una licencia personal, limitada, no exclusiva, no transferible y revocable para utilizar la app en dispositivos Apple compatibles conforme a estos términos.","## 7. Disponibilidad y responsabilidad","Podemos actualizar, modificar o retirar funciones. La disponibilidad puede depender de iOS, iCloud, permisos, redes o proveedores de terceros. En la medida permitida por la ley, Renuvia se ofrece tal como está y no respondemos por decisiones tomadas sin revisar los datos, interrupciones de terceros o daños indirectos. Esta limitación no se aplica a responsabilidades que no puedan excluirse legalmente.","## 8. Apple como tercero beneficiario","Cuando obtienes Renuvia desde el App Store, Apple es un tercero beneficiario de estos términos y puede hacerlos cumplir frente a ti según las reglas aplicables del App Store. Apple no está obligada a prestar mantenimiento o soporte de Renuvia.","## 9. Ley y contacto","Se aplica la legislación de España, sin perjuicio de las normas imperativas y derechos de consumo del lugar donde resides. Contacto: Lester Romero Bernardo (RomeroDev), Valencia, España; romerodev.app+renuvia@gmail.com."],"body_en":["These terms govern the international use of Renuvia. By downloading or using the app, you accept these terms, the Privacy Policy, and the applicable App Store rules. Non-waivable consumer rights are not limited.","## 1. Service","Renuvia is a tool for organizing dates, documents, and renewals. It does not provide legal, financial, medical, tax, or contractual advice, does not guarantee that a date is correct, and does not replace document review or professional advice.","## 2. Your data and responsibility","You keep your rights in content you enter or import and confirm that you are allowed to use it. You are responsible for reviewing every date, title, cost, reminder, export, and calendar action before relying on it, and for protecting your device, Apple Account, and exported copies.","## 3. Acceptable use","Do not use Renuvia for unlawful purposes, fraud, impersonation, unauthorized access, malware, improper surveillance, infringement, or entering third-party data without permission. Do not interfere with the app or bypass its controls except where applicable law expressly permits it.","## 4. OCR and automation","OCR, barcode detection, and automated suggestions may omit data, make mistakes, or interpret a source incompletely. User review is required before saving a result or creating reminders, events, actions, or renewals.","## 5. Purchases and Apple services","Pro features are offered through Apple In-App Purchase and are subject to Renuvia's published subscription terms and the information Apple displays before purchase. Apple independently provides the App Store, payments, iCloud, and other third-party platforms.","## 6. Intellectual property","Renuvia, its code, brand, design, text, and own materials belong to Lester Romero Bernardo (RomeroDev) or its licensors. You receive a personal, limited, non-exclusive, non-transferable, revocable license to use the app on compatible Apple devices under these terms.","## 7. Availability and liability","We may update, change, or remove features. Availability may depend on iOS, iCloud, permissions, networks, or third-party providers. To the extent permitted by law, Renuvia is provided as is and we are not responsible for decisions made without reviewing data, third-party interruptions, or indirect damages. This limitation does not apply to liability that cannot legally be excluded.","## 8. Apple as third-party beneficiary","When you obtain Renuvia from the App Store, Apple is a third-party beneficiary of these terms and may enforce them against you under the applicable App Store rules. Apple is not required to provide maintenance or support for Renuvia.","## 9. Law and contact","Spanish law applies, without prejudice to mandatory rules and consumer rights in your place of residence. Contact: Lester Romero Bernardo (RomeroDev), Valencia, Spain; romerodev.app+renuvia@gmail.com."]},"subscriptions":{"title":"Condiciones de suscripción de Renuvia Pro","title_en":"Renuvia Pro Subscription Terms","updatedAt":"2026-08-28","body":["Estas condiciones complementan los Términos de uso y la Política de privacidad de Renuvia. La disponibilidad, el precio, los impuestos y la moneda pueden variar por país o región; la información contractual final es la que Apple muestra antes de confirmar.","## 1. Planes y valor continuo","Renuvia Pro ofrece suscripciones auto-renovables mensual y anual para expedientes ilimitados, playbooks personalizados, captura avanzada, exportaciones y sincronización opcional. La suscripción ofrece valor continuo mientras las funciones Pro estén disponibles y evolucionen.","## 2. Precio y compra","Apple procesa el pago mediante In-App Purchase y carga el importe a tu Apple Account. Antes de confirmar, Apple muestra el precio local, duración, impuestos aplicables, moneda y condiciones de la oferta. Los importes mostrados en esta web son orientativos y nunca sustituyen el precio del App Store de tu territorio.","## 3. Prueba gratuita y renovación","Cuando Apple ofrece una prueba gratuita de 7 días y la cuenta es elegible, no se realiza el cargo durante la prueba. Si no cancelas al menos 24 horas antes de que termine, comenzará la suscripción de pago mostrada y se renovará automáticamente por el mismo periodo salvo cancelación. Apple puede realizar el cargo dentro de las 24 horas anteriores a la renovación.","## 4. Gestionar o cancelar","Puedes gestionar o cancelar la suscripción desde Ajustes > tu nombre > Suscripciones en el iPhone o iPad, o desde la página de suscripciones de Apple. Eliminar Renuvia no cancela la suscripción. La cancelación evita renovaciones futuras y normalmente mantiene el acceso hasta el final del periodo pagado.","## 5. Restaurar compras y estados pendientes","Renuvia incluye Restaurar compras para recuperar un acceso adquirido con el mismo Apple Account. Las compras pendientes, rechazadas, reembolsadas, revocadas o no verificables pueden mantener bloqueadas las funciones Pro hasta que Apple confirme el estado.","## 6. Cambios, reembolsos y derechos locales","Apple puede cambiar precios y comunicará o solicitará consentimiento según sus reglas y la legislación aplicable. Apple gestiona reembolsos, disputas de facturación y pagos mediante reportaproblem.apple.com. Nada de estas condiciones limita derechos de desistimiento, reembolso o protección del consumidor que sean obligatorios en tu territorio.","## 7. Fin del acceso Pro","Cuando finalice el periodo pagado, las funciones Pro se desactivarán y podrás seguir usando las funciones gratuitas disponibles. La cancelación o expiración no borra automáticamente tus datos locales ni tus exportaciones.","## 8. Contacto","Soporte de compras y suscripciones: romerodev.app+renuvia@gmail.com. Responsable: Lester Romero Bernardo (RomeroDev), Valencia, España."],"body_en":["These terms complement Renuvia's Terms of Use and Privacy Policy. Availability, price, taxes, and currency may vary by country or region; the final contractual information is what Apple displays before confirmation.","## 1. Plans and ongoing value","Renuvia Pro offers monthly and annual auto-renewable subscriptions for unlimited dossiers, custom playbooks, advanced capture, exports, and optional sync. The subscription provides ongoing value while Pro features are available and evolve.","## 2. Price and purchase","Apple processes payment through In-App Purchase and charges your Apple Account. Before confirmation, Apple displays the local price, duration, applicable taxes, currency, and offer terms. Prices shown on this website are indicative and never replace the App Store price for your territory.","## 3. Free trial and renewal","When Apple offers a 7-day free trial and the account is eligible, no charge is made during the trial. Unless you cancel at least 24 hours before it ends, the displayed paid subscription begins and renews automatically for the same period unless canceled. Apple may charge within the 24 hours before renewal.","## 4. Manage or cancel","You can manage or cancel in Settings > your name > Subscriptions on iPhone or iPad, or through Apple's subscription page. Deleting Renuvia does not cancel the subscription. Cancellation prevents future renewals and normally keeps access until the paid period ends.","## 5. Restore purchases and pending states","Renuvia includes Restore Purchases to recover access bought with the same Apple Account. Pending, declined, refunded, revoked, or unverifiable transactions may keep Pro features locked until Apple confirms the state.","## 6. Changes, refunds, and local rights","Apple may change prices and will notify or request consent under its rules and applicable law. Apple handles refunds, billing disputes, and payment issues through reportaproblem.apple.com. Nothing in these terms limits mandatory withdrawal, refund, or consumer-protection rights in your territory.","## 7. End of Pro access","When the paid period ends, Pro features are disabled and you can continue using the free features then available. Cancellation or expiration does not automatically delete local data or exports.","## 8. Contact","Purchase and subscription support: romerodev.app+renuvia@gmail.com. Controller: Lester Romero Bernardo (RomeroDev), Valencia, Spain."]}},"pricing":[{"name":"Mensual","name_en":"Monthly","price":"2,99 €","cadence":"/mes","cadence_en":"/month","description":"7 días de prueba para cuentas elegibles; renovación mensual.","description_en":"7-day trial for eligible accounts; monthly renewal.","isIndicative":true},{"name":"Anual","name_en":"Annual","price":"29,90 €","cadence":"/año","cadence_en":"/year","description":"7 días de prueba para cuentas elegibles; mejor valor anual.","description_en":"7-day trial for eligible accounts; best annual value.","badge":"Mejor valor","badge_en":"Best value","featured":true,"isIndicative":true}],"freeFeatures":["Entrada manual ilimitada","Radar de preparación","Playbooks esenciales","Datos locales y revisión OCR"],"freeFeatures_en":["Unlimited manual entry","Readiness Radar","Essential playbooks","Local data and OCR review"],"proFeatures":["Expedientes ilimitados","Playbooks personalizados","Checklist y documentos avanzados","Historial de renovación","Exportación CSV/JSON e iCloud opcional"],"proFeatures_en":["Unlimited dossiers","Custom playbooks","Advanced checklists and documents","Renewal history","CSV/JSON export and optional iCloud"]}]$catalog$::jsonb;
  product jsonb;
  product_id uuid;
  faq_item jsonb;
  legal_item jsonb;
  faq_order integer;
begin
  for product in select value from jsonb_array_elements(catalog)
  loop
    insert into public.apps (
      slug, name, tagline, tagline_en, short_description, short_description_en,
      long_description, long_description_en, problem, problem_en, benefits,
      benefits_en, features, features_en, audience, audience_en, status,
      featured, category, platform, app_store_url, website_url, support_email,
      icon_url, cover_image_url, screenshots, video_url, primary_cta_label,
      primary_cta_label_en, primary_cta_url, secondary_cta_label,
      secondary_cta_label_en, secondary_cta_url, color_primary, color_secondary,
      seo_title, seo_description, seo_image, pricing, free_features,
      free_features_en, pro_features, pro_features_en, bundle_identifier,
      version, build_number, follow_enabled, published_at, updated_at
    ) values (
      product->>'slug', product->>'name', product->>'tagline', product->>'tagline_en',
      product->>'shortDescription', product->>'shortDescription_en',
      product->>'longDescription', product->>'longDescription_en',
      product->>'problem', product->>'problem_en',
      array(select jsonb_array_elements_text(coalesce(product->'benefits', '[]'::jsonb))),
      array(select jsonb_array_elements_text(coalesce(product->'benefits_en', '[]'::jsonb))),
      array(select jsonb_array_elements_text(coalesce(product->'features', '[]'::jsonb))),
      array(select jsonb_array_elements_text(coalesce(product->'features_en', '[]'::jsonb))),
      product->>'audience', product->>'audience_en', product->>'status',
      coalesce((product->>'featured')::boolean, false), product->>'category',
      array(select jsonb_array_elements_text(coalesce(product->'platform', '[]'::jsonb))),
      nullif(product->>'appStoreUrl', ''), nullif(product->>'websiteUrl', ''),
      product->>'supportEmail', nullif(product->>'iconUrl', ''),
      nullif(product->>'coverImageUrl', ''),
      array(select jsonb_array_elements_text(coalesce(product->'screenshots', '[]'::jsonb))),
      nullif(product->>'videoUrl', ''), product->>'primaryCtaLabel',
      nullif(product->>'primaryCtaLabel_en', ''), product->>'primaryCtaUrl',
      nullif(product->>'secondaryCtaLabel', ''), nullif(product->>'secondaryCtaLabel_en', ''),
      nullif(product->>'secondaryCtaUrl', ''), nullif(product->>'colorPrimary', ''),
      nullif(product->>'colorSecondary', ''), product#>>'{seo,title}',
      product#>>'{seo,description}', nullif(product#>>'{seo,image}', ''),
      coalesce(product->'pricing', '[]'::jsonb),
      array(select jsonb_array_elements_text(coalesce(product->'freeFeatures', '[]'::jsonb))),
      array(select jsonb_array_elements_text(coalesce(product->'freeFeatures_en', '[]'::jsonb))),
      array(select jsonb_array_elements_text(coalesce(product->'proFeatures', '[]'::jsonb))),
      array(select jsonb_array_elements_text(coalesce(product->'proFeatures_en', '[]'::jsonb))),
      nullif(product->>'bundleIdentifier', ''), nullif(product->>'version', ''),
      nullif(product->>'buildNumber', ''),
      coalesce((product->>'followEnabled')::boolean, true),
      nullif(product->>'publishedAt', '')::timestamptz, now()
    )
    on conflict (slug) do update set
      name = excluded.name, tagline = excluded.tagline, tagline_en = excluded.tagline_en,
      short_description = excluded.short_description, short_description_en = excluded.short_description_en,
      long_description = excluded.long_description, long_description_en = excluded.long_description_en,
      problem = excluded.problem, problem_en = excluded.problem_en, benefits = excluded.benefits,
      benefits_en = excluded.benefits_en, features = excluded.features, features_en = excluded.features_en,
      audience = excluded.audience, audience_en = excluded.audience_en, status = excluded.status,
      featured = excluded.featured, category = excluded.category, platform = excluded.platform,
      app_store_url = excluded.app_store_url, website_url = excluded.website_url,
      support_email = excluded.support_email, icon_url = excluded.icon_url,
      cover_image_url = excluded.cover_image_url, screenshots = excluded.screenshots,
      video_url = excluded.video_url, primary_cta_label = excluded.primary_cta_label,
      primary_cta_label_en = excluded.primary_cta_label_en, primary_cta_url = excluded.primary_cta_url,
      secondary_cta_label = excluded.secondary_cta_label,
      secondary_cta_label_en = excluded.secondary_cta_label_en,
      secondary_cta_url = excluded.secondary_cta_url, color_primary = excluded.color_primary,
      color_secondary = excluded.color_secondary, seo_title = excluded.seo_title,
      seo_description = excluded.seo_description, seo_image = excluded.seo_image,
      pricing = excluded.pricing, free_features = excluded.free_features,
      free_features_en = excluded.free_features_en, pro_features = excluded.pro_features,
      pro_features_en = excluded.pro_features_en, bundle_identifier = excluded.bundle_identifier,
      version = excluded.version, build_number = excluded.build_number,
      follow_enabled = excluded.follow_enabled, published_at = excluded.published_at,
      updated_at = now()
    returning id into product_id;

    delete from public.app_faqs where app_id = product_id;
    faq_order := 0;
    for faq_item in select value from jsonb_array_elements(coalesce(product->'faq', '[]'::jsonb))
    loop
      insert into public.app_faqs (app_id, question, question_en, answer, answer_en, sort_order)
      values (
        product_id, faq_item->>'question', nullif(faq_item->>'question_en', ''),
        faq_item->>'answer', nullif(faq_item->>'answer_en', ''), faq_order
      );
      faq_order := faq_order + 1;
    end loop;

    delete from public.app_legal_pages where app_id = product_id;
    for legal_item in
      select value from jsonb_array_elements(jsonb_build_array(
        jsonb_build_object('kind', 'privacy', 'page', product#>'{legal,privacy}'),
        jsonb_build_object('kind', 'terms', 'page', product#>'{legal,terms}'),
        jsonb_build_object('kind', 'subscriptions', 'page', product#>'{legal,subscriptions}'),
        jsonb_build_object('kind', 'safety', 'page', product#>'{legal,safety}')
      ))
    loop
      if legal_item->'page' is not null and legal_item->'page' <> 'null'::jsonb then
        insert into public.app_legal_pages (app_id, kind, title, title_en, body, body_en, updated_at)
        values (
          product_id, legal_item->>'kind', legal_item#>>'{page,title}',
          nullif(legal_item#>>'{page,title_en}', ''),
          array_to_string(array(select jsonb_array_elements_text(coalesce(legal_item#>'{page,body}', '[]'::jsonb))), E'\n'),
          array_to_string(array(select jsonb_array_elements_text(coalesce(legal_item#>'{page,body_en}', '[]'::jsonb))), E'\n'),
          coalesce(nullif(legal_item#>>'{page,updatedAt}', '')::timestamptz, now())
        );
      end if;
    end loop;
  end loop;
end
$migration$;

insert into public.app_media (app_id, kind, path, alt, alt_en, source, sort_order)
select id, 'icon', icon_url, 'Icono de ' || name, name || ' app icon', 'apps.icon_url', 0
from public.apps
where slug = 'renuvia' and icon_url is not null
on conflict do nothing;

insert into public.app_media (app_id, kind, path, alt, alt_en, source, sort_order)
select id, 'cover', cover_image_url, 'Vista de ' || name, name || ' product view', 'apps.cover_image_url', 1
from public.apps
where slug = 'renuvia' and cover_image_url is not null
on conflict do nothing;

insert into public.app_catalog_audits (app_id, source_path, score, missing_fields)
select id, '/Volumes/SSD Externo/DESARROLLO/iOS/Renuvia', 84,
  ARRAY['public_download', 'video']::text[]
from public.apps
where slug = 'renuvia'
on conflict (app_id) do update set
  source_path = excluded.source_path,
  score = excluded.score,
  missing_fields = excluded.missing_fields,
  verified_at = now();
